function clamp01(s: any, vname: any): any {
  let v: any;
  v = s.var(vname);
  return [s.if(s.lt(v, 0), [s.setVar(vname, 0)]), s.if(s.gt(v, 1), [s.setVar(vname, 1)])];
}

function clampR(s: any, vname: any, lo: any, hi: any): any {
  let v: any;
  v = s.var(vname);
  return [s.if(s.lt(v, lo), [s.setVar(vname, lo)]), s.if(s.gt(v, hi), [s.setVar(vname, hi)])];
}

